 *
 * Given an array nums of n integers and an integer target, are there elements a, b, c, and d in nums 
 * such that a + b + c + d = target? Find all unique quadruplets in the array which gives the sum of 
 * target.
 * 
 * Note:
 * 
 * The solution set must not contain duplicate quadruplets.
 * 
 * Example:
 * 
 * Given array nums = [1, 0, -1, 0, -2, 2], and target = 0.
 * 
 * A solution set is:
 * [
 *   [-1,  0, 0, 1],
 *   [-2, -1, 1, 2],
 *   [-2,  0, 0, 2]
 * ]
 * 
 ******************************************************************************************************/

// 已经在三数之和中总结出n数之和
// 再写一遍

//time 45 mem 29
func fourSum(nums []int, target int) [][]int {
	if len(nums)<1{
		return nil
	}
	sort.Slice(nums, func(i, j int) bool {
		return nums[i]<nums[j]
	})
	return nSum(nums,target,0,4)
}
func nSum(nums []int,target,start,n int)[][]int{
	if n<2 || n>len(nums){
		return nil
	}
	sz:=len(nums)
	l,r:=start,sz-1
	ans:=[][]int{}
	if n==2{
		for l<r{
			left,right:=nums[l],nums[r]
			sum:=left+right
			if sum==target{
				ans = append(ans, []int{left,right})
				for l<r && nums[l]==left{l++}
				for l<r && nums[r]==right{r--}
			}else if sum<target{
				for l<r && nums[l]==left{l++}
			}else if sum>target{
				for l<r && nums[r]==right{r--}
			}
		}
	}else{
		for i:=start;i<sz;i++{
			sub:=nSum(nums,target-nums[i],i+1,n-1)
			for _,v:=range sub{
				ans = append(ans,append(v,nums[i]))
			}
			for i<sz-1&&nums[i]==nums[i+1]{i++}
		}
	}
	return ans
}

class Solution {
public:
    vector<vector<int>> fourSum(vector<int>& nums, int target) {
        sort(begin(nums), end(nums));
        return kSum(nums, target, 0, 4);
    }

    vector<vector<int>> kSum(vector<int>& nums, long long target, int start, int k) {
        vector<vector<int>> res;

        // If we have run out of numbers to add, return res.
        if (start == nums.size()) {
            return res;
        }

        // There are k remaining values to add to the sum. The 
        // average of these values is at least target / k.
        long long average_value = target / k;

        // We cannot obtain a sum of target if the smallest value
        // in nums is greater than target / k or if the largest 
        // value in nums is smaller than target / k.
        if  (nums[start] > average_value || average_value > nums.back()) {
            return res;
        }

        if (k == 2) {
            return twoSum(nums, target, start);
        }

        for (int i = start; i < nums.size(); ++i) {
            if (i == start || nums[i - 1] != nums[i]) {
                for (vector<int>& subset : kSum(nums, static_cast<long long>(target) - nums[i], i + 1, k - 1)) {
                    res.push_back({nums[i]});
                    res.back().insert(end(res.back()), begin(subset), end(subset));
                }
            }
        }

        return res;
    }

    vector<vector<int>> twoSum(vector<int>& nums, long long target, int start) {
        vector<vector<int>> res;
        int lo = start, hi = int(nums.size()) - 1;

        while (lo < hi) {
            int curr_sum = nums[lo] + nums[hi];
            if (curr_sum < target || (lo > start && nums[lo] == nums[lo - 1])) {
                ++lo;
            } else if (curr_sum > target || (hi < nums.size() - 1 && nums[hi] == nums[hi + 1])) {
                --hi;
            } else {
                res.push_back({ nums[lo++], nums[hi--] });
            }
        }

        return res;
    }
};

